// ============================================================================
// Root Store
// ============================================================================

export class RootStore {
  user: UserStore
  adminUser: AdminUserStore
  paymentSettings: PaymentSettingsStore
  service: ServiceStore
  deposit: DepositStore
  order: OrderStore
  walletTransaction: WalletTransactionStore
  notification: NotificationStore
  supportTicket: SupportTicketStore
  plan: PlanStore
  userPlan: UserPlanStore
  siteSettings: SiteSettingsStore

  constructor() {
    this.user = new UserStore()
    this.adminUser = new AdminUserStore()
    this.paymentSettings = new PaymentSettingsStore()
    this.service = new ServiceStore()
    this.deposit = new DepositStore()
    this.order = new OrderStore()
    this.walletTransaction = new WalletTransactionStore()
    this.notification = new NotificationStore()
    this.supportTicket = new SupportTicketStore()
    this.plan = new PlanStore()
    this.userPlan = new UserPlanStore()
    this.siteSettings = new SiteSettingsStore()
    makeAutoObservable(this)
  }

  /** Clear all stores */
  clearAll() {
    this.user.clear()
    this.adminUser.clear()
    this.paymentSettings.clear()
    this.service.clear()
    this.deposit.clear()
    this.order.clear()
    this.walletTransaction.clear()
    this.notification.clear()
    this.supportTicket.clear()
    this.plan.clear()
    this.userPlan.clear()
    this.siteSettings.clear()
  }
}

// ============================================================================
// Factory & Singleton
// ============================================================================

let rootStore: RootStore | null = null

/**
 * Get or create the root store singleton
 */
export function getStore(): RootStore {
  if (!rootStore) {
    rootStore = new RootStore()
  }
  return rootStore
}

/**
 * Create a new root store (for testing or SSR)
 */
export function createStore(): RootStore {
  return new RootStore()
}

/**
 * Reset the singleton store
 */
export function resetStore(): void {
  rootStore = null
}
